// HR//0D -- MonitorScreenRaster: turns laid-out lines into the actual pixels of the CRT glass.
// Assembly: HRZeroDay.Game  (UnityEngine types only: Color32 / Texture2D)
// Owner: Agent (written) / Dev A (owns it afterwards). Started 2026-11-26.
//
// WHY RASTERISE AT RUNTIME INSTEAD OF USING TextMeshPro
//   1. TMP font assets are built by an editor GUI -- they cannot be generated headlessly, so the CI
//      gate could never verify them. The 5x7 atlas is generated by tools/art/make_font.py and gated.
//   2. A 5x7 hinted TTF at 480x270 renders blurry at fractional scales; compositing exact glyph
//      pixels cannot.
//   3. ONE 142x88 texture for the whole screen = one sprite = one draw call, and the glass clips by
//      construction: there is no geometry that could spill past the bezel (BUG-028).
//
// The raster is deliberately pure: it takes an IGlyphSource and writes a Color32[], so the tests can
// prove clipping and colour without a Unity runtime.

using System;
using System.Collections.Generic;
using UnityEngine;

namespace HRZeroDay.Game
{
    /// <summary>Where glyph pixels come from. Implemented by the atlas loader and by the tests.</summary>
    public interface IGlyphSource
    {
        int CellW { get; }
        int CellH { get; }
        /// <summary>True when the glyph has ink at (gx, gy), glyph-local, y DOWN from the glyph top.</summary>
        bool InkAt(char ch, int gx, int gy);
        /// <summary>Palette colour for a colour key (see Palette in make_art_kit.py).</summary>
        Color32 Colour(string key);
    }

    public static class MonitorScreenRaster
    {
        /// <summary>
        /// Turns a PNG-ordered buffer (row 0 = TOP) into what Texture2D.SetPixels32 expects (row 0 =
        /// BOTTOM-left). Every view that composites text MUST call this before SetPixels32.
        ///
        /// This is the bug that made the after-hours walk render upside-down on 2026-11-26
        /// (screenshot: mirrored glyphs on the wrong side of the page). The raster is documented as
        /// top-down, SetPixels32 is bottom-up, and the conversion was missing in the views -- the tests
        /// could not catch it because they read the buffer, not the texture.
        /// </summary>
        public static void FlipToTextureOrder(Color32[] buffer, int w, int h)
        {
            if (buffer == null || w <= 0 || h <= 0 || buffer.Length < w * h) return;
            Color32 swap;
            for (int y = 0; y < h / 2; y++)
            {
                int top = y * w, bottom = (h - 1 - y) * w;
                for (int x = 0; x < w; x++)
                {
                    swap = buffer[top + x];
                    buffer[top + x] = buffer[bottom + x];
                    buffer[bottom + x] = swap;
                }
            }
        }

        /// <summary>
        /// Fills `buffer` (w*h, row 0 = TOP of the glass) with the lines. Everything is clipped to the
        /// buffer: a line that does not fit is simply not drawn below the last row.
        /// </summary>
        public static void Render(Color32[] buffer, int w, int h,
                                  IList<ScreenLine> lines,
                                  IGlyphSource glyphs,
                                  Color32 background,
                                  bool paintBackground = true)
        {
            if (buffer == null) throw new ArgumentNullException(nameof(buffer));
            if (glyphs == null) throw new ArgumentNullException(nameof(glyphs));
            if (buffer.Length < w * h) throw new ArgumentException("buffer too small for " + w + "x" + h);

            // paintBackground:false lets a caller own the fill (the after-hours sweep draws a caption band
            // first and needs the glyphs composited ON it, not on a flat colour). Default stays true, so
            // every existing caller behaves exactly as before and its tests still hold.
            if (paintBackground)
                for (int i = 0; i < buffer.Length; i++) buffer[i] = background;
            if (lines == null) return;

            // LinesToRects hands back y-UP canvas space. The texture is row 0 = top, so flip once here.
            for (int li = 0; li < lines.Count; li++)
            {
                var line = lines[li];
                if (string.IsNullOrEmpty(line.text)) continue;
                Color32 ink = glyphs.Colour(line.colour);

                int topRow = (h - 1) - (int)line.canvasY - (MonitorScreen.GlyphH - 1); // canvasY is the BOX bottom
                int penX = 0;
                for (int ci = 0; ci < line.text.Length; ci++)
                {
                    char ch = line.text[ci];
                    for (int gy = 0; gy < MonitorScreen.GlyphH; gy++)
                    {
                        int ty = topRow + gy;
                        if (ty < 0 || ty >= h) continue;
                        for (int gx = 0; gx < MonitorScreen.GlyphW; gx++)
                        {
                            int tx = penX + gx;
                            if (tx < 0 || tx >= w) continue;
                            if (glyphs.InkAt(ch, gx, gy)) buffer[ty * w + tx] = ink;
                        }
                    }
                    penX += MonitorScreen.GlyphW + MonitorScreen.LetterGap;
                }
            }
        }

        /// <summary>Count of pixels that are not the background -- used by tests and the editor menu.</summary>
        public static int InkPixelCount(Color32[] buffer, Color32 background)
        {
            int n = 0;
            for (int i = 0; i < buffer.Length; i++)
            {
                var c = buffer[i];
                if (c.r != background.r || c.g != background.g || c.b != background.b) n++;
            }
            return n;
        }
    }
}
